// ANCHOR: example
//! Includes Rust source generated by the package build script.

include!(concat!(env!("OUT_DIR"), "/generated_message.rs"));

/// Prints a constant generated during the Cargo build.
fn main() {
    println!("{GENERATED_MESSAGE}");
}
// ANCHOR_END: example

/// Runs the generated-source example.
pub fn run() {
    main();
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Verifies that generated source is written to `OUT_DIR` and included.
    #[test]
    fn generated_message_is_available_to_rust_code() {
        assert_eq!(GENERATED_MESSAGE, "Generated during the Cargo build.");
    }

    #[test]
    fn test_main_entry_point() {
        main();
    }
}
